.roc-ui-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  gap: 8px;
  min-height: 36px;
  padding: 8px 15px;
  border: 1px solid transparent;
  border-radius: var(--roc-radius, 8px);
  font-weight: 500;
  line-height: 1.2;
  cursor: pointer;
  white-space: nowrap;
  text-decoration: none;
  transition:
    background-color 140ms,
    box-shadow 140ms;
}
.roc-ui-button.roc-ui-button-variant-default {
