  background: var(--roc-paper, #fff);
}
.roc-ui-button.roc-ui-button-variant-ghost,
.roc-ui-button.roc-ui-button-variant-link {
  background: transparent;
}
.roc-ui-button.roc-ui-button-variant-link {
  text-decoration: underline;
  text-underline-offset: 4px;
}
.roc-ui-button:hover:not(:disabled) {
  box-shadow: inset 0 0 0 100px #80808018;
}
.roc-ui-button.roc-ui-button-size-xs {
  min-height: 26px;
  padding: 4px 8px;
  font-size: 11px;
}
.roc-ui-button.roc-ui-button-size-sm {
  min-height: 32px;
  padding: 6px 12px;
}
.roc-ui-button.roc-ui-button-size-lg {
  min-height: 42px;
  padding: 11px 22px;
}
.roc-ui-button:is(
  .roc-ui-button-size-icon,
  .roc-ui-button-size-icon-xs,
  .roc-ui-button-size-icon-sm,
  .roc-ui-button-size-icon-lg
) {
  padding: 0;
  width: 36px;
  height: 36px;
}
.roc-ui-button.roc-ui-button-size-icon-xs {
  width: 26px;
  height: 26px;
  min-height: 26px;
}
.roc-ui-button.roc-ui-button-size-icon-sm {
  width: 32px;
  height: 32px;
  min-height: 32px;
}
.roc-ui-button.roc-ui-button-size-icon-lg {
  width: 42px;
  height: 42px;
}
.roc-ui-button[aria-busy="true"] {
  cursor: progress;
}

.roc-ui-button-label {
  display: inline-grid;
  align-items: center;
}
.roc-ui-button-label > span {
  grid-area: 1 / 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
@keyframes roc-ui-reveal {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}

